SourceCode.Declaration:
/// <summary>
/// Single source of truth for the shared ABS grid row-colour palette.
/// Light tints chosen to remain readable with the default (dark) grid text.
/// Use from form data source displayOption() overrides to keep status/severity
/// colouring consistent across all ABS and ABSCore monitor/analysis forms.
/// </summary>
public final class ABSUIColors
{
}

Method.Source:
/// <summary>Red tint — critical / overdue / below safety stock.</summary>
public static int critical()
{
    return WinAPI::RGB2int(255, 199, 206);
}

/// <summary>Orange tint — high concern / excess.</summary>
public static int warning()
{
    return WinAPI::RGB2int(255, 190, 100);
}

/// <summary>Amber tint — medium concern / at risk.</summary>
public static int caution()
{
    return WinAPI::RGB2int(255, 235, 156);
}

/// <summary>Green tint — healthy / on time / no issue.</summary>
public static int healthy()
{
    return WinAPI::RGB2int(198, 239, 206);
}

/// <summary>Blue tint — informational / low severity / in progress.</summary>
public static int info()
{
    return WinAPI::RGB2int(187, 222, 251);
}

/// <summary>Grey tint — neutral / no demand / planned.</summary>
public static int neutral()
{
    return WinAPI::RGB2int(240, 240, 240);
}

/// <summary>Near-white tint — empty / zero-value cells that should recede.</summary>
public static int muted()
{
    return WinAPI::RGB2int(248, 248, 248);
}

/// <summary>Blue tint — ABC class A (highest importance). Cool/importance scale, NOT a health judgement.</summary>
public static int segmentA()
{
    return WinAPI::RGB2int(187, 222, 251);
}

/// <summary>Teal tint — ABC class B (medium importance).</summary>
public static int segmentB()
{
    return WinAPI::RGB2int(178, 223, 219);
}

/// <summary>Grey tint — ABC class C (lowest importance).</summary>
public static int segmentC()
{
    return WinAPI::RGB2int(224, 224, 224);
}
